window.COBIT_CONTROLS = window.COBIT_CONTROLS || [];
window.COBIT_CONTROLS.push(...
[
{"objective":"APO01","purpose":"BT yönetim çerçevesi; politikaları, süreçleri, rolleri, organizasyon yapılarını ve bunları destekleyen araçları tek ve tutarlı bir sistemde birleştirir. Bu çerçeve olmadan kontroller kişilere bağımlı kalır, sorumluluklar belirsizleşir ve yönetim kararları sahaya tutarlı biçimde yansımaz. İyi tasarlanmış bir çerçeve, diğer tüm COBIT hedefleri için ortak zemin oluşturur.","auditFocus":"Kıdemli denetçi, çerçevenin kâğıt üzerinde kalıp kalmadığını; politikaların, rollerin ve komitelerin gerçekte işleyip işlemediğini ve karar kayıtlarıyla desteklenip desteklenmediğini sorgular. Özellikle sahiplik, yetki seviyeleri, politika istisnaları ve iyileştirme döngüsünün izlenebilirliği üzerinde yoğunlaşır.","keyRisks":["Rol ve yetkilerin belirsiz olması nedeniyle kritik kararların sahipsiz kalması","Güncelliğini yitirmiş veya uygulanmayan politikaların yanlış güvence vermesi","Veri ve sistem sahipliği tanımlanmadığı için erişim ve sınıflandırma kararlarının gelişigüzel verilmesi"],"practices":[
{"code":"APO01.01","name":"Design the management system for enterprise I&T.","title":"BT yönetim sisteminin kurum ihtiyaçlarına göre tasarlanması","expectation":"Kurum hedeflerinden türetilmiş, hangi yönetim hedeflerinin öncelikli olduğunu ve bunların hangi bileşenlerle (süreç, yapı, politika, bilgi akışı) destekleneceğini gösteren onaylı bir tasarım belgesi beklenir. Tasarım; risk profili, kurum büyüklüğü, düzenleyici ortam ve kaynak modeli gibi faktörler dikkate alınarak hazırlanmalı, kuruma göre belirlenmiş aralıklarla veya önemli değişikliklerde gözden geçirilmelidir. Tasarımın sahibi ve onay mercii açıkça tanımlı olmalıdır.","design":"Tasarımın kurum hedefleri ve risk profiliyle izlenebilir bir bağ kurup kurmadığı, kapsam dışı bırakılan alanların gerekçelendirilip gerekçelendirilmediği incelenir.","operating":"Dönem içindeki gözden geçirme ve güncelleme kayıtları ile önemli organizasyonel değişiklikler karşılaştırılır; değişikliklerin tasarıma yansıyıp yansımadığı seçilen olaylar üzerinden doğrulanır.","evidence":["Onaylı BT yönetim sistemi tasarım belgesi veya yönetişim çerçevesi","Hedef kaskadı ya da öncelikli yönetim hedeflerini gösteren analiz","Tasarımın gözden geçirildiğini gösteren toplantı tutanakları ve sürüm geçmişi"],"findings":["Yönetim sistemi tasarımı yazılı değildir; uygulamalar birimlerin kendi alışkanlıklarına göre şekillenmektedir.","Tasarım belgesi mevcuttur ancak son organizasyon değişikliği ve yeni bulut hizmet modeli sonrasında güncellenmemiştir."],"iso":[],"clauses":["4.1","4.3","4.4"],"itgc":""},
{"code":"APO01.02","name":"Communicate management objectives, direction and decisions made.","title":"Yönetim hedef ve kararlarının paydaşlara iletilmesi","expectation":"Üst yönetimin BT’ye ilişkin hedefleri, öncelikleri ve aldığı önemli kararlar ilgili paydaşlara planlı bir iletişim yaklaşımıyla duyurulmalıdır. İletişimin içeriği, hedef kitlesi, kanalı ve sıklığı kuruma göre belirlenmiş olmalı; temel mesajların anlaşıldığı anket, geri bildirim veya toplantı katılımı gibi yollarla izlenmelidir.","design":"İletişim planının hedef kitleleri ve mesaj sahiplerini tanımlayıp tanımlamadığı ve kritik kararların ilgili ekiplere ulaşmasını güvenceye alacak bir mekanizma içerip içermediği değerlendirilir.","operating":"Dönem içinde alınan önemli yönetim kararları listelenir; risk bazlı seçilen kararlar için duyuru kayıtları, dağıtım listeleri ve geri bildirim izleri incelenir.","evidence":["BT iletişim planı veya iletişim takvimi","Yönetim kararlarını içeren duyuru, e-posta veya intranet yayınları","Bilgilendirme toplantılarının katılım ve sunum kayıtları","Çalışan farkındalık anketi veya geri bildirim sonuçları"],"findings":["Yönetim düzeyinde alınan BT önceliklendirme kararları operasyon ekiplerine yazılı olarak iletilmemiştir.","İletişim faaliyetleri yürütülmektedir ancak mesajların anlaşılıp anlaşılmadığına dair herhangi bir ölçüm bulunmamaktadır."],"iso":[],"clauses":["5.1","7.4"],"itgc":""},
{"code":"APO01.03","name":"Implement management processes (to support the achievement of governance and management objectives).","title":"Yönetim süreçlerinin hedef olgunluk seviyeleriyle devreye alınması","expectation":"Yönetim sistemi tasarımında öncelikli görülen süreçler için hedef yetkinlik (olgunluk) seviyeleri ve devreye alma sırası belirlenmiş olmalıdır. Her sürecin sahibi, girdileri, çıktıları ve ölçütleri tanımlanmalı; mevcut ve hedef seviye arasındaki fark kuruma göre belirlenmiş aralıklarla değerlendirilerek iyileştirme planına bağlanmalıdır.","design":"Hedef seviyelerin iş önceliği ve risk değerlendirmesiyle gerekçelendirilip gerekçelendirilmediği ve her süreç için sahip ile ölçüt tanımlanıp tanımlanmadığı incelenir.","operating":"Süreç envanterinden risk bazlı seçilen süreçlerin olgunluk değerlendirme sonuçları, dayanak kanıtları ve iyileştirme aksiyonlarının takibi yeniden incelenir.","evidence":["Süreç envanteri ve süreç sahipleri listesi","Hedef ve mevcut olgunluk seviyelerini gösteren değerlendirme raporu","Süreç iyileştirme yol haritası ve aksiyon takip kaydı"],"findings":["Süreçler için hedef olgunluk seviyeleri belirlenmiştir ancak bu seviyelerin neden seçildiğine dair gerekçe yoktur.","Olgunluk değerlendirmesi yalnızca öz beyana dayanmakta olup beyanları destekleyen kanıt toplanmamaktadır."],"iso":[],"clauses":["4.4","9.1"],"itgc":""},
{"code":"APO01.04","name":"Define and implement the organizational structures.","title":"BT yönetişim komiteleri ve organizasyon yapılarının kurulması","expectation":"BT yönlendirme komitesi, mimari kurul veya değişiklik danışma kurulu gibi yapıların görev tanımı, üyeliği, karar yetkisi ve toplanma sıklığı kuruma göre belirlenmiş şekilde yazılı olmalıdır. Dış hizmet sağlayıcılarla kurulan ortak yönetişim yapıları da kapsamda yer almalı ve komitelerin aldığı kararlar izlenebilir biçimde kayda geçirilmelidir.","design":"Komite görev tanımlarının yetki sınırlarını, nisap kurallarını, raporlama hattını ve çıkar çatışması yönetimini kapsayıp kapsamadığı değerlendirilir.","operating":"Dönem boyunca planlanan ve gerçekleşen toplantılar karşılaştırılır; seçilen toplantılarda nisap, karar kaydı ve aksiyonların kapanışı tutanaklar üzerinden doğrulanır.","evidence":["Komite görev tanımları ve üyelik listeleri","Toplantı takvimi ve onaylı tutanaklar","Komite kararlarına ait aksiyon takip listesi","Güncel organizasyon şeması"],"findings":["BT yönlendirme komitesi dönem içinde planlanan toplantıların bir kısmını gerçekleştirmemiş, bekleyen kararlar ertelenmiştir.","Komite tutanaklarında alınan kararlar yer almakta ancak sorumlu ve hedef tarih belirtilmemektedir."],"iso":["5.4"],"clauses":["5.1","5.3"],"itgc":""},
{"code":"APO01.05","name":"Establish roles and responsibilities.","title":"BT rol, sorumluluk ve yetki seviyelerinin tanımlanması","expectation":"BT ile ilgili kritik faaliyetler için sorumlu, hesap verebilir, danışılan ve bilgilendirilen tarafları gösteren bir sorumluluk matrisi (ör. RACI) ve güncel görev tanımları bulunmalıdır. Onay limitleri ve imza yetkileri yazılı olmalı, görevler ayrılığı ilkesiyle uyumlu tasarlanmalı ve rol değişikliklerinde güncellenmelidir.","design":"Matrisin çakışan veya sahipsiz faaliyet bırakıp bırakmadığı ve birbiriyle bağdaşmayan görevlerin (ör. geliştirme ile canlıya aktarım) aynı role verilip verilmediği analiz edilir.","operating":"Dönem içindeki rol değişiklikleri ve yeni atamalar listelenir; seçilen örneklerde görev tanımı, yetki onayı ve sistem yetkilerinin tanımlı rolle uyumu incelenir.","evidence":["Onaylı RACI matrisi veya sorumluluk dağılım tablosu","Güncel görev tanımları","Yetki ve onay limitleri yönergesi","Görevler ayrılığı çatışma analizi"],"findings":["Görev tanımları uzun süre önce hazırlanmış olup mevcut rollerle uyumlu değildir.","Aynı kişinin hem değişiklik geliştirme hem de canlı ortama aktarım yetkisine sahip olduğu ve telafi edici kontrol tanımlanmadığı görülmüştür."],"iso":["5.2","5.3","5.4"],"clauses":["5.3"],"itgc":""},
{"code":"APO01.06","name":"Optimize the placement of the IT function.","title":"BT fonksiyonunun organizasyondaki konumunun belirlenmesi","expectation":"BT fonksiyonunun raporlama hattı, kurum için taşıdığı stratejik önem ve operasyonel bağımlılık dikkate alınarak bilinçli bir kararla belirlenmiş olmalıdır. BT yöneticisinin üst yönetime erişimi, bütçe ve önceliklendirme kararlarına katılımı ile bilgi güvenliği gibi gözetim fonksiyonlarının bağımsızlığı değerlendirilmiş olmalıdır.","design":"Konumlandırma kararının alternatifleri değerlendiren belgelenmiş bir analize dayanıp dayanmadığı ve gözetim fonksiyonlarının denetledikleri alanlardan yeterince bağımsız olup olmadığı incelenir.","operating":"Dönem içindeki üst yönetim toplantılarına BT temsilcisinin katılımı ve BT’nin kritik kararlara dahil edildiği örnekler tutanaklar üzerinden doğrulanır.","evidence":["Güncel organizasyon şeması ve raporlama hatları","Konumlandırma kararına ilişkin yönetim kararı veya analiz","Üst yönetim toplantı tutanaklarındaki BT gündem maddeleri"],"findings":["Bilgi güvenliği fonksiyonu, gözetlemesi beklenen BT altyapı yöneticisine raporlamaktadır.","BT yöneticisi stratejik planlama toplantılarına davet edilmemekte, kararlar kendisine sonradan bildirilmektedir."],"iso":[],"clauses":[],"itgc":""},
{"code":"APO01.07","name":"Define information (data) and system ownership.","title":"Bilgi (veri) ve sistem sahipliğinin tanımlanması","expectation":"Kritik bilgi varlıkları ve uygulamalar için iş tarafında bir sahip atanmış olmalı; sahipler sınıflandırma, erişim onayı ve periyodik erişim gözden geçirme sorumluluklarını bilmelidir. Sahiplik bilgisi envanterde tutulmalı ve kişi ayrılışı veya organizasyon değişikliğinde güncellenmelidir.","design":"Sahiplik tanımının sınıflandırma ve erişim yönetimi süreçleriyle bağlantılı olup olmadığı ve sahipsiz varlık kalmasını önleyecek bir kontrol bulunup bulunmadığı değerlendirilir.","operating":"Uygulama ve veri envanterinin tamlığı CMDB veya lisans kayıtları gibi bağımsız kaynaklarla karşılaştırılır; risk bazlı seçilen kritik sistemlerde sahibin aktif çalışan olduğu ve erişim gözden geçirmelerini onayladığı doğrulanır.","evidence":["Sahip bilgisi içeren bilgi varlığı ve uygulama envanteri","Bilgi sınıflandırma politikası ve sınıflandırma kayıtları","Veri sahiplerince onaylanmış erişim gözden geçirme çıktıları"],"findings":["Envanterdeki bazı kritik uygulamalarda sahip olarak kurumdan ayrılmış kişiler görünmektedir.","Sahiplik tümüyle BT birimine atanmış olup iş birimlerinin erişim ve sınıflandırma kararlarına katılımı bulunmamaktadır."],"iso":["5.9","5.12","5.13","5.15"],"clauses":[],"itgc":"access"},
{"code":"APO01.08","name":"Define target skills and competencies.","title":"Hedef beceri ve yetkinliklerin tanımlanması","expectation":"Yönetim hedeflerini gerçekleştirmek için gereken teknik ve yönetsel yetkinlikler bir yetkinlik çerçevesinde tanımlanmış ve rollerle ilişkilendirilmiş olmalıdır. Çerçeve, yeni teknolojiler ve iş modeli değişiklikleri doğrultusunda kuruma göre belirlenmiş aralıklarla güncellenmelidir.","design":"Yetkinlik tanımlarının rol bazında ölçülebilir olup olmadığı ve güvenlik, bulut, veri gibi kritik alanların kapsanıp kapsanmadığı değerlendirilir.","operating":"Güncelleme kayıtları incelenir; seçilen rollerde tanımlı yetkinliklerin işe alım ilanlarında, eğitim planlarında ve performans değerlendirmelerinde fiilen kullanıldığı doğrulanır.","evidence":["Rol bazlı BT yetkinlik çerçevesi veya yetkinlik matrisi","Yetkinlik çerçevesinin güncelleme ve onay kayıtları","Yetkinliklerle ilişkilendirilmiş iş ilanı veya eğitim planı örnekleri"],"findings":["Yetkinlik matrisi bulunmakla birlikte bulut ve siber güvenlik gibi yeni ihtiyaç alanlarını kapsamamaktadır.","Tanımlı yetkinlikler eğitim planlamasında ve işe alım süreçlerinde referans alınmamaktadır."],"iso":[],"clauses":["7.2"],"itgc":""},
{"code":"APO01.09","name":"Define and communicate policies and procedures.","title":"Politika ve prosedürlerin tanımlanması, duyurulması ve uyumun izlenmesi","expectation":"BT politika ve prosedürleri bir belge hiyerarşisi içinde, sahibi ve onay mercii belli olacak şekilde yazılı olmalı ve çalışanlara erişilebilir biçimde yayınlanmalıdır. Belgeler kuruma göre belirlenmiş aralıklarla veya önemli değişikliklerde gözden geçirilmeli; uyum izlenmeli, istisnalar onaylı ve süreli olmalı, ihlallerin sonuçları tanımlı olmalıdır.","design":"Politika yönetim sürecinin sürüm kontrolü, istisna yönetimi, uyum ölçümü ve ihlal sonuçlarını kapsayıp kapsamadığı değerlendirilir.","operating":"Politika envanterindeki tüm belgelerin gözden geçirme tarihleri kontrol edilir; risk bazlı seçilen istisnaların onay ve süre koşulları ile uyum izleme sonuçları incelenir.","evidence":["Sürüm ve onay bilgisi içeren politika ve prosedür envanteri","Politika istisna kayıtları ve onayları","Çalışanların politika okuma ve kabul kayıtları","Politika uyum izleme raporları"],"findings":["Bazı politikaların gözden geçirme tarihi geçmiş olup içerdikleri roller güncel organizasyonla uyuşmamaktadır.","Politika istisnaları e-posta ile onaylanmakta, merkezi bir kayıt ve bitiş tarihi bulunmamaktadır."],"iso":["5.1","5.36","5.37"],"clauses":["5.2","7.5"],"itgc":""},
{"code":"APO01.10","name":"Define and implement infrastructure, services and applications to support the governance and management system.","title":"Yönetim sistemini destekleyen araç ve altyapının sağlanması","expectation":"Yönetişim faaliyetlerini destekleyen araçlar (GRC platformu, risk kaydı, politika portalı, mimari depo, hizmet yönetimi aracı) ihtiyaca göre seçilmiş, sahibi tanımlı ve erişimi kontrol altında olmalıdır. Bu araçlardaki bilginin doğruluğu ve güncelliği için sorumluluk atanmalı, araçların yeterliliği kuruma göre belirlenmiş aralıklarla gözden geçirilmelidir.","design":"Araçların veri bütünlüğü, erişim yetkilendirmesi ve kayıt saklama gereksinimlerini karşılayacak biçimde yapılandırılıp yapılandırılmadığı değerlendirilir.","operating":"Araçlardaki kayıtların tamlığı ve güncelliği seçilen örneklerde kaynak belgelerle karşılaştırılır; yönetici yetkisine sahip kullanıcı listesi salt okunur olarak incelenir.","evidence":["Yönetişim araçları listesi ve sahiplik bilgisi","Araçlardaki rol ve yetki raporları (salt okunur dışa aktarım)","Risk kaydı veya politika portalından alınmış güncel kayıt görünümleri"],"findings":["Risk kaydı elektronik tablolarda tutulmakta, sürüm kontrolü ve değişiklik izi bulunmamaktadır.","GRC aracında yönetici yetkisine sahip kullanıcıların bir kısmı görevi gereği bu yetkiye ihtiyaç duymamaktadır."],"iso":[],"clauses":["7.1","7.5"],"itgc":""},
{"code":"APO01.11","name":"Manage continual improvement of the I&T management system.","title":"BT yönetim sisteminin sürekli iyileştirilmesi","expectation":"Yönetim sisteminin etkinliği; denetim bulguları, olaylar, performans ölçümleri ve paydaş geri bildirimleri gibi girdilerle kuruma göre belirlenmiş aralıklarla değerlendirilmelidir. İyileştirme fırsatları önceliklendirilerek sahipli ve tarihli aksiyonlara dönüştürülmeli, kapanışları ve etkileri doğrulanmalıdır.","design":"İyileştirme sürecinin farklı kaynaklardan gelen girdileri tek bir kayıtta toplayıp toplamadığı, önceliklendirme kriteri ve etkinlik doğrulaması içerip içermediği kontrol edilir.","operating":"Dönem içinde açılan iyileştirme aksiyonlarının tamamı listelenir; seçilen kapanmış aksiyonlarda kök neden, uygulanan değişiklik ve etkinlik kanıtı yeniden incelenir.","evidence":["Sürekli iyileştirme veya aksiyon takip kaydı","Yönetim gözden geçirme toplantı tutanakları","Kapanmış aksiyonlara ait etkinlik doğrulama kanıtları"],"findings":["Önceki denetim bulgularına ait aksiyonlar kapatılmış görünmekte, ancak kapanışı destekleyen kanıt bulunmamaktadır.","İyileştirme önerileri toplanmakta fakat önceliklendirilmeden bekletilmektedir."],"iso":["5.35"],"clauses":["9.3","10.1","10.2"],"itgc":""}
]},
{"objective":"APO02","purpose":"BT stratejisi, kurumun iş hedeflerine ulaşmak için hangi dijital yeteneklere, hangi sırayla ve ne kadar kaynakla yatırım yapacağını belirler. Stratejiden kopuk bir BT, kaynakları önceliksiz işlere harcar ve iş birimlerinin beklentileriyle çatışır. Net bir yol haritası yatırım ve risk kararlarını da tutarlı kılar.","auditFocus":"Denetçi, stratejinin iş stratejisinden izlenebilir şekilde türetilip türetilmediğini ve mevcut durum ile hedef durum arasındaki farkın gerçekçi bir yol haritasına dönüştürülüp dönüştürülmediğini inceler. Ayrıca stratejinin onaylanıp duyurulduğunu ve uygulamanın ölçülerek izlendiğini kanıtlarla arar.","keyRisks":["BT yatırımlarının iş önceliklerinden kopuk ve dağınık yapılması","Mevcut yeteneklerin gerçekçi değerlendirilmemesi nedeniyle ulaşılamaz hedeflerin belirlenmesi","Stratejinin paydaşlarca bilinmemesi sonucu birimlerin çelişen girişimler başlatması"],"practices":[
{"code":"APO02.01","name":"Understand enterprise context and direction.","title":"Kurumsal bağlamın ve iş yönünün anlaşılması","expectation":"BT stratejisi hazırlanmadan önce sektör eğilimleri, düzenleyici beklentiler, rekabet koşulları ve kurumun dijitalleşme hedefi analiz edilmiş olmalıdır. Bu analiz iş birimleriyle birlikte yapılmalı, kurumsal stratejiye açıkça referans vermeli ve her stratejik planlama döngüsünde güncellenmelidir.","design":"Bağlam analizinin iş stratejisi, düzenleyici ortam ve risk iştahı gibi temel girdileri kapsayıp kapsamadığı ve iş temsilcilerinin katılımını güvenceye alıp almadığı değerlendirilir.","operating":"Son planlama döngüsünde kullanılan analiz belgeleri, çalıştay kayıtları ve paydaş görüşme notları incelenerek analizin gerçekten yapıldığı ve stratejiye girdi oluşturduğu doğrulanır.","evidence":["Kurumsal strateji belgesi ve BT stratejisinin buna yaptığı atıflar","Çevre ve bağlam analizi (ör. PESTEL, SWOT) çıktıları","İş birimleriyle yapılan strateji çalıştaylarının katılım ve not kayıtları"],"findings":["BT stratejisi, kurumsal strateji güncellenmeden önceki varsayımlara dayanmaktadır.","Bağlam analizi yalnızca BT ekibince yapılmış, iş birimlerinin görüşü alınmamıştır."],"iso":[],"clauses":["4.1","4.2"],"itgc":""},
{"code":"APO02.02","name":"Assess current capabilities, performance and digital maturity of the enterprise.","title":"Mevcut BT yetenekleri, performansı ve dijital olgunluğun değerlendirilmesi","expectation":"Mevcut BT hizmetlerinin performansı, iç ve dış kaynaklı yetenekler, teknoloji varlıkları ve dijital olgunluk düzeyi nesnel verilere dayanarak değerlendirilmelidir. Değerlendirme; hizmet seviyesi raporları, kullanıcı memnuniyeti, teknik borç ve tedarikçi performansı gibi girdileri içermeli ve bir başlangıç noktası olarak kayıt altına alınmalıdır.","design":"Değerlendirme yönteminin tanımlı kriterler kullanıp kullanmadığı ve sonuçların varsayım yerine ölçülmüş verilere dayanıp dayanmadığı incelenir.","operating":"Değerlendirme raporundaki seçilmiş tespitler kaynak verilerle (hizmet seviyesi raporları, envanter, anket sonuçları) karşılaştırılarak yeniden doğrulanır.","evidence":["Mevcut durum veya dijital olgunluk değerlendirme raporu","Hizmet performansı ve kullanıcı memnuniyeti verileri","Uygulama ve altyapı yaşam döngüsü (teknik borç) analizi"],"findings":["Mevcut durum değerlendirmesi yalnızca yönetici görüşlerine dayanmakta, ölçülmüş performans verisi kullanılmamaktadır.","Dış kaynaklı hizmetler değerlendirme kapsamına alınmamıştır."],"iso":[],"clauses":[],"itgc":""},
{"code":"APO02.03","name":"Define target digital capabilities.","title":"Hedef dijital yeteneklerin belirlenmesi","expectation":"İş yönünden hareketle ulaşılmak istenen BT ürün, hizmet ve yetenekleri hedef durum olarak tanımlanmalıdır. Hedefler ölçülebilir olmalı, referans çerçeveler ve sektör uygulamaları dikkate alınmalı, güvenlik ve uyum gereksinimleri tasarımın parçası olarak ele alınmalıdır.","design":"Hedef yeteneklerin iş hedefleriyle ilişkilendirilip ilişkilendirilmediği, ölçülebilir başarı kriterleri ile güvenlik ve uyum gereksinimleri içerip içermediği değerlendirilir.","operating":"Seçilen hedef yetenekler için iş sahibinin onayı, başarı ölçütleri ve sonraki planlama belgelerinde tutarlı kullanımı izlenir.","evidence":["Hedef durum yetenek haritası","Hedeflerin iş hedefleriyle eşleştirildiği izlenebilirlik tablosu","Hedef durumun onaylandığını gösteren yönetim kararı"],"findings":["Hedef durum genel ifadelerle tanımlanmış olup ölçülebilir başarı kriteri içermemektedir.","Hedef yetenekler tanımlanırken bilgi güvenliği ve süreklilik gereksinimleri dikkate alınmamıştır."],"iso":[],"clauses":[],"itgc":""},
{"code":"APO02.04","name":"Conduct a gap analysis.","title":"Mevcut ve hedef durum arasındaki fark analizi","expectation":"Mevcut ve hedef durum arasındaki farklar süreç, teknoloji, insan kaynağı ve tedarikçi boyutlarında belirlenmeli, kurumsal mimari üzerindeki yüksek seviyeli değişiklikler tanımlanmalıdır. Her fark için etki, bağımlılık ve kabaca kaynak ihtiyacı belirtilerek önceliklendirmeye hazır hale getirilmelidir.","design":"Fark analizinin tüm boyutları kapsayıp kapsamadığı ve farkların önceliklendirme için yeterli bilgiyi (etki, risk, maliyet) içerip içermediği incelenir.","operating":"Fark analizindeki seçili maddelerin yol haritasında karşılığı olup olmadığı kontrol edilir; karşılığı olmayanlar için bilinçli bir erteleme kararı aranır.","evidence":["Fark analizi raporu veya tablosu","Farkların etki ve öncelik değerlendirmesi","Fark analizinin yol haritasıyla eşleştirmesi"],"findings":["Fark analizi yalnızca teknoloji boyutunu ele almakta, yetkinlik ve süreç farklarını kapsamamaktadır.","Belirlenen bazı kritik farkların yol haritasında karşılığı bulunmamakta, erteleme kararı da kayıt altında değildir."],"iso":[],"clauses":[],"itgc":""},
{"code":"APO02.05","name":"Define the strategic plan and road map.","title":"Dijital strateji ve yol haritasının oluşturulması","expectation":"Fark analizine dayanan BT ve dijital strateji ile yol haritası; girişimleri, sıralamayı, bağımlılıkları, sorumluları, kaynak ihtiyacını ve ölçülebilir hedefleri içermelidir. Strateji ilgili paydaşların katılımıyla hazırlanmalı, yetkili merci tarafından onaylanmalı ve uygulama ilerlemesi kuruma göre belirlenmiş aralıklarla raporlanmalıdır.","design":"Yol haritasının girişimleri iş hedefleriyle ilişkilendirip ilişkilendirmediği, ölçüt ve sorumlu tanımlayıp tanımlamadığı ve resmi onay sürecinden geçip geçmediği değerlendirilir.","operating":"Dönem içindeki ilerleme raporları yol haritasıyla karşılaştırılır; seçilen girişimlerde sapmaların raporlandığı ve yönetimin karar aldığı doğrulanır.","evidence":["Onaylı BT veya dijital strateji belgesi","Yol haritası ve girişim listesi","Strateji ilerleme raporları ve yönetim değerlendirme tutanakları","Strateji performans göstergesi tanımları"],"findings":["Stratejik plan onaylanmış ancak uygulama ilerlemesi hiçbir yönetim kuruluna raporlanmamıştır.","Yol haritasındaki girişimlerin sorumluları ve kaynak tahminleri tanımlanmamıştır."],"iso":[],"clauses":[],"itgc":""},
{"code":"APO02.06","name":"Communicate the I&T strategy and direction.","title":"BT stratejisinin ve yönünün paydaşlara duyurulması","expectation":"Onaylanan BT stratejisi, hedef kitleye uygun düzeyde özetlenerek iş birimlerine, BT ekiplerine ve gerektiğinde kritik tedarikçilere duyurulmalıdır. Duyurunun kapsamı ve kanalları kuruma göre belirlenmiş olmalı; gizli stratejik bilgilerin paylaşımı sınıflandırma kurallarına uygun yapılmalıdır.","design":"İletişim yaklaşımının farklı hedef kitleleri ve bilgi gizlilik seviyelerini dikkate alıp almadığı incelenir.","operating":"Strateji onayından sonra yapılan duyurular, sunumlar ve dağıtım kayıtları incelenir; seçilen ekiplerle yapılan görüşmelerle stratejinin bilinirliği doğrulanır.","evidence":["Strateji duyuru materyalleri ve sunumları","Dağıtım listeleri veya intranet yayın kayıtları","Bilgilendirme oturumlarının katılım kayıtları"],"findings":["Strateji yalnızca üst yönetimle paylaşılmış, uygulamadan sorumlu ekipler önceliklerden habersizdir.","Gizli olarak sınıflandırılmış stratejik plan, erişim kısıtlaması olmayan ortak bir klasörde paylaşılmıştır."],"iso":[],"clauses":["7.4"],"itgc":""}
]},
{"objective":"APO03","purpose":"Kurumsal mimari; iş süreçleri, veri, uygulama ve teknoloji katmanlarının birbirine nasıl bağlandığını gösterir ve değişikliklerin bu bütünle uyumlu yapılmasını sağlar. Mimari yönetişim olmadan tekrarlayan sistemler, entegrasyon karmaşası ve kontrol edilemeyen teknik borç birikir. Ortak ilke ve standartlar, güvenliğin ve yeniden kullanılabilirliğin tasarım aşamasında sağlanmasına yardım eder.","auditFocus":"Denetçi, mimari ilke ve standartların yazılı olup olmadığını ve projelerin bu standartlara uygunluğunun gerçekten bir mimari gözden geçirmeyle kontrol edilip edilmediğini inceler. Mimari deponun güncelliğini ve standart dışı çözümler için istisna yönetimini de kanıtlar üzerinden değerlendirir.","keyRisks":["Projelerin mimari standartlara uyulmadan devreye alınması sonucu entegrasyon ve güvenlik zayıflıklarının oluşması","Güncel olmayan mimari belgeler nedeniyle değişiklik etkilerinin yanlış değerlendirilmesi","Tekrarlayan uygulama ve teknolojiler nedeniyle maliyet ve karmaşıklığın artması"],"practices":[
{"code":"APO03.01","name":"Develop the enterprise architecture vision.","title":"Kurumsal mimari vizyonunun oluşturulması","expectation":"İş, veri, uygulama ve teknoloji katmanlarını kapsayan, mevcut ve hedef mimariyi yüksek seviyede tarif eden onaylı bir mimari vizyon belgesi bulunmalıdır. Vizyon; kapsamı, mimari ilkeleri, paydaşları ve beklenen iş faydasını tanımlamalı ve BT stratejisiyle tutarlı olmalıdır.","design":"Vizyonun BT stratejisine ve iş hedeflerine bağlanıp bağlanmadığı ve uygulanabilir mimari ilkeler (ör. yeniden kullanım, güvenli tasarım) içerip içermediği değerlendirilir.","operating":"Vizyonun onay ve güncelleme kayıtları incelenir; seçilen proje belgelerinde vizyondaki ilkelere atıf yapılıp yapılmadığı kontrol edilir.","evidence":["Onaylı mimari vizyon belgesi","Mimari ilkeler listesi","Vizyonun BT stratejisiyle ilişkisini gösteren eşleştirme"],"findings":["Mimari vizyon yalnızca teknoloji katmanını ele almakta, veri ve iş süreçleri boyutlarını içermemektedir.","Mimari ilkeler tanımlanmış ancak yönetim tarafından onaylanmamış ve projelere duyurulmamıştır."],"iso":[],"clauses":[],"itgc":""},
{"code":"APO03.02","name":"Define reference architecture.","title":"Referans mimarinin tanımlanması ve güncel tutulması","expectation":"Mevcut ve hedef mimari; iş yetenekleri, veri modelleri, uygulama portföyü, entegrasyonlar ve teknoloji standartları düzeyinde bir mimari depoda tutulmalıdır. Onaylı teknoloji standartları ve güvenlik mimarisi ilkeleri referans mimarinin parçası olmalı, depo değişikliklerle birlikte güncellenmelidir.","design":"Referans mimarinin onaylı teknoloji listesi, güvenlik ilkeleri ve veri akışlarını içerip içermediği ve güncelleme sorumluluğunun atanıp atanmadığı incelenir.","operating":"Mimari depodaki kayıtlar seçilen örneklerde canlı ortam envanteri ve son devreye alınan sistemlerle karşılaştırılarak güncellik doğrulanır.","evidence":["Mimari depo veya modelleme aracından alınmış görünümler","Onaylı teknoloji standartları listesi","Uygulama ve entegrasyon haritası"],"findings":["Mimari depodaki uygulama haritası son dönemde devreye alınan sistemleri içermemektedir.","Üretici desteği sona ermiş bazı teknolojiler onaylı standartlar listesinde hâlâ yer almaktadır."],"iso":["5.9","8.27"],"clauses":[],"itgc":""},
{"code":"APO03.03","name":"Select opportunities and solutions.","title":"Mimari fırsatların ve çözüm seçeneklerinin seçilmesi","expectation":"Mevcut ve hedef mimari arasındaki farklar iş ve teknik açıdan değerlendirilerek anlamlı iş paketleri ve projeler halinde gruplanmalıdır. Çözüm seçeneklerinin karşılaştırılması maliyet, risk, yeniden kullanım ve mimari uyum kriterleriyle belgelenmeli, önceliklendirme kararı yetkili mercide alınmalıdır.","design":"Çözüm seçim kriterlerinin tanımlı olup olmadığı ve mimari uyum ile güvenlik risklerinin karar kriterleri arasında yer alıp almadığı değerlendirilir.","operating":"Dönem içinde seçilen çözümler için alternatif değerlendirmesi, kriter puanlaması ve onay kayıtları yeniden incelenir.","evidence":["Çözüm seçeneklerinin karşılaştırma analizleri","Mimari kurul karar kayıtları","Önceliklendirilmiş iş paketi veya proje listesi"],"findings":["Çözüm seçimi tek bir tedarikçi teklifine göre yapılmış, alternatifler belgelenmemiştir.","Aynı işlevi gören yeni bir uygulama, mevcut kurumsal çözüm değerlendirilmeden satın alınmıştır."],"iso":[],"clauses":[],"itgc":""},
{"code":"APO03.04","name":"Define architecture implementation.","title":"Mimari uygulama ve geçiş planının oluşturulması","expectation":"Hedef mimariye geçiş için program ve proje portföyüyle uyumlu, bağımlılıkları ve geçiş aşamalarını gösteren uygulanabilir bir plan bulunmalıdır. Plan; geçiş dönemindeki geçici çözümleri, emekliye ayrılacak sistemleri, veri taşıma ve güvenlik gereksinimlerini kapsamalıdır.","design":"Geçiş planının portföy planlarıyla tutarlı olup olmadığı ve sistem emekliye ayırma, veri taşıma ve güvenlik konularını ele alıp almadığı değerlendirilir.","operating":"Planlanan geçiş adımları gerçekleşmelerle karşılaştırılır; seçilen emekliye ayırma işlemlerinde veri arşivleme ve erişim kapatma kayıtları incelenir.","evidence":["Mimari geçiş planı veya yol haritası","Sistem emekliye ayırma planları ve tamamlama kayıtları","Geçiş planının portföy planlarıyla eşleştirmesi"],"findings":["Yeni sisteme geçiş tamamlanmış ancak eski sistem kapatılmadığı için iki paralel veri kaynağı kullanılmaya devam etmektedir.","Geçiş planında veri taşıma doğrulaması ve güvenlik gereksinimleri yer almamaktadır."],"iso":["5.8"],"clauses":[],"itgc":""},
{"code":"APO03.05","name":"Provide enterprise architecture services.","title":"Kurumsal mimari hizmetlerinin sunulması ve projelere rehberlik","expectation":"Mimari ekip projelere rehberlik etmeli, kritik tasarım kararlarını bir mimari gözden geçirme sürecinden geçirmeli ve standart dışı çözümler için gerekçeli, onaylı ve süreli istisna kararları üretmelidir. Mimari uyum, kuruma göre belirlenmiş tetikleyicilerle (ör. proje aşama geçişleri) kontrol edilmelidir.","design":"Mimari gözden geçirmenin proje yaşam döngüsünde zorunlu bir kontrol noktası olarak tanımlanıp tanımlanmadığı ve istisna sürecinin risk kabulü içerip içermediği değerlendirilir.","operating":"Dönem içindeki projelerin tam listesi alınır; risk bazlı seçilen projelerde mimari gözden geçirme kaydı, bulguların kapatılması ve istisna onayları incelenir.","evidence":["Mimari gözden geçirme kontrol listesi ve tamamlanmış örnekler","Mimari istisna kaydı ve onayları","Proje aşama geçiş kayıtları"],"findings":["Bazı projeler mimari gözden geçirme yapılmadan canlıya alınmıştır.","Mimari istisnalar süresiz verilmekte ve sonradan takip edilmemektedir."],"iso":["5.8","8.27"],"clauses":[],"itgc":"sdlc"}
]},
{"objective":"APO04","purpose":"İnovasyon yönetimi, yeni teknolojilerin ve fikirlerin kontrollü biçimde keşfedilmesini, denenmesini ve değer üretebilecek olanların kuruma kazandırılmasını sağlar. Yapılandırılmış bir yaklaşım yoksa ya fırsatlar kaçırılır ya da denetimsiz denemeler güvenlik ve uyum riskleri doğurur. Denetçi açısından önemli olan, inovasyon için kullanılan kaynakların ve doğan risklerin görünür olmasıdır.","auditFocus":"Denetçi, teknoloji izleme ve fikir değerlendirme faaliyetlerinin tanımlı kriterlerle yürütülüp yürütülmediğini ve kavram kanıtı (PoC) çalışmalarının veri koruma ve güvenlik açısından kontrollü ortamda yapılıp yapılmadığını inceler. Başarılı denemelerin olağan yatırım, mimari ve değişiklik süreçlerine düzgün aktarılıp aktarılmadığına da bakar.","keyRisks":["Kontrolsüz deneme ve pilot çalışmalarda gerçek kişisel veya gizli verinin korumasız kullanılması","Kurumsal onay alınmadan kullanılmaya başlanan yeni teknolojilerin gölge BT oluşturması","Rekabet açısından kritik teknolojik gelişmelerin zamanında fark edilmemesi"],"practices":[
{"code":"APO04.01","name":"Create an environment conducive to innovation.","title":"İnovasyonu destekleyen ortamın oluşturulması","expectation":"Kurumda fikir toplama kanalı, değerlendirme mekanizması ve inovasyona ayrılmış zaman veya bütçe gibi destekleyici unsurlar tanımlı olmalıdır. Tanınma ve ödüllendirme yaklaşımı yazılı olmalı; fikirlerin kimden geldiği ve nasıl sonuçlandığı izlenebilmelidir.","design":"Fikir toplama ve değerlendirme mekanizmasının şeffaf kriterlere sahip olup olmadığı ve fikri mülkiyet ile gizlilik konularını ele alıp almadığı değerlendirilir.","operating":"Dönem içindeki fikir kayıtları incelenir; seçilen fikirlerin değerlendirme sonucu, öneri sahibine verilen geri bildirim ve ödüllendirme kayıtları doğrulanır.","evidence":["İnovasyon politikası veya program tanımı","Fikir yönetim platformu kayıtları","İnovasyona ayrılan bütçe veya kaynak kayıtları"],"findings":["Çalışanlardan gelen öneriler kayıt altına alınmakta ancak değerlendirme sonucu öneri sahibine iletilmemektedir.","İnovasyon faaliyetleri için ayrılmış bir kaynak veya sorumlu bulunmamaktadır."],"iso":[],"clauses":[],"itgc":""},
{"code":"APO04.02","name":"Maintain an understanding of the enterprise environment.","title":"Kurumun iş ortamının ve ihtiyaçlarının izlenmesi","expectation":"İnovasyondan sorumlu ekip veya kişi, iş birimlerinin sorunlarını ve stratejik önceliklerini düzenli temaslarla anlamalı ve bunları inovasyon gündemine dönüştürmelidir. Bu etkileşimler kuruma göre belirlenmiş bir düzende yapılmalı ve sonuçları kayıt altına alınmalıdır.","design":"İş birimleriyle etkileşim mekanizmasının (ör. ihtiyaç çalıştayları, iş ilişkisi yöneticileri) tanımlı olup olmadığı ve çıktılarının inovasyon gündemine bağlanıp bağlanmadığı değerlendirilir.","operating":"Seçilen iş birimleriyle yapılan toplantı kayıtları ve bu toplantılardan doğan inovasyon gündem maddeleri izlenir.","evidence":["İş birimleriyle ihtiyaç toplantısı kayıtları","İnovasyon gündemi veya ihtiyaç listesi","İş ilişkisi yöneticisi rol tanımı"],"findings":["İnovasyon gündemi büyük ölçüde teknoloji tedarikçilerinin önerilerine dayanmakta, iş ihtiyaçları sistematik olarak toplanmamaktadır.","İş birimleriyle yapılan görüşmeler kayıt altına alınmadığı için takip edilememektedir."],"iso":[],"clauses":[],"itgc":""},
{"code":"APO04.03","name":"Monitor and scan the technology environment.","title":"Teknoloji ortamının izlenmesi ve taranması","expectation":"Yeni ve gelişmekte olan teknolojileri, sektör eğilimlerini ve kullanılan teknolojilerin yaşam döngüsü değişikliklerini sistematik olarak izleyen bir teknoloji takip süreci bulunmalıdır. Kaynaklar, sorumlular ve raporlama sıklığı kuruma göre belirlenmiş olmalı; bulgular ilgili karar alıcılara iletilmelidir.","design":"İzleme sürecinin tanımlı kaynaklara, değerlendirme kriterlerine ve raporlama hattına sahip olup olmadığı incelenir.","operating":"Dönem içinde üretilen teknoloji izleme raporları incelenir; seçilen tespitlerin mimari veya strateji kararlarına girdi oluşturup oluşturmadığı izlenir.","evidence":["Teknoloji radarı veya izleme raporları","Teknoloji izleme sorumluluk ve kaynak tanımı","Raporların sunulduğu toplantı tutanakları"],"findings":["Teknoloji izleme kişisel inisiyatife bağlı olup düzenli bir çıktı üretilmemektedir.","Kullanılan bir teknolojinin üretici desteğinin sona ereceği bilgisi karar alıcılara zamanında ulaşmamıştır."],"iso":[],"clauses":[],"itgc":""},
{"code":"APO04.04","name":"Assess the potential of emerging technologies and innovative ideas.","title":"Yeni teknolojilerin ve fikirlerin potansiyelinin değerlendirilmesi","expectation":"Umut vadeden teknoloji ve fikirler iş faydası, maliyet, risk ve uygulanabilirlik açısından değerlendirilmeli, gerekirse sınırlı kapsamlı kavram kanıtı (PoC) ile denenmelidir. PoC çalışmaları onaylı kapsam, başarı kriteri ve süreyle yürütülmeli; gerçek veri kullanılacaksa maskeleme veya anonimleştirme gibi koruma önlemleri önceden belirlenmelidir.","design":"PoC onay sürecinin başarı kriterlerini, güvenlik değerlendirmesini ve veri kullanım kurallarını içerip içermediği değerlendirilir.","operating":"Dönem içindeki PoC’lerin tamamı listelenir; risk bazlı seçilenlerde onay, kullanılan veri türü, güvenlik değerlendirmesi, deneme sonrası veri silme ve sonuç raporu incelenir.","evidence":["PoC talep ve onay formları","PoC sonuç ve değerlendirme raporları","PoC’lerde kullanılan verilere ilişkin güvenlik ve veri koruma değerlendirmesi"],"findings":["Bulut tabanlı bir PoC’de maskelenmemiş müşteri verisi kullanılmış ve deneme sonrasında silindiği doğrulanmamıştır.","PoC’ler başarı kriteri tanımlanmadan başlatılmış, bu nedenle sonuçlar nesnel olarak değerlendirilememiştir."],"iso":["5.34","8.33"],"clauses":[],"itgc":""},
{"code":"APO04.05","name":"Recommend appropriate further initiatives.","title":"Başarılı denemeler için ileri girişim önerilmesi","expectation":"PoC sonuçları değerlendirildikten sonra devam edilmesi önerilen girişimler, iş durumu taslağıyla birlikte yatırım ve portföy yönetim sürecine aktarılmalıdır. Öneriler paydaş desteğini ve gereken kaynakları açıkça göstermeli; devam edilmeyen denemelerin kapanış kararı da kayda geçirilmelidir.","design":"PoC’den kalıcı kullanıma geçişin olağan portföy, mimari ve değişiklik süreçlerini atlamasını önleyen bir kontrol noktası bulunup bulunmadığı değerlendirilir.","operating":"Dönem içinde tamamlanan PoC’lerin akıbeti izlenir; seçilen örneklerde öneri belgesi, karar kaydı ve portföye aktarım kanıtı incelenir.","evidence":["Girişim öneri belgeleri ve iş durumu taslakları","İnovasyon veya portföy kurulu karar kayıtları","Sonlandırılan PoC’lere ait kapanış kayıtları"],"findings":["Bir pilot çalışma resmi yatırım kararı alınmadan kalıcı kullanıma geçmiştir.","Devam edilmeyen PoC’ler için kapanış kararı ve kaynakların serbest bırakıldığına dair kayıt bulunmamaktadır."],"iso":[],"clauses":[],"itgc":""},
{"code":"APO04.06","name":"Monitor the implementation and use of innovation.","title":"İnovasyonların uygulanmasının ve kullanımının izlenmesi","expectation":"Benimsenen yenilikler, devreye alındıktan sonra beklenen faydayı ne ölçüde sağladıkları, entegrasyon sorunları ve ortaya çıkan riskler açısından yaşam döngüsü boyunca izlenmelidir. Sonuçlar ve çıkarılan dersler gelecekteki inovasyon kararlarına aktarılmalıdır.","design":"Devreye alınan yenilikler için fayda ölçütleri, izleme sorumluluğu ve risk değerlendirmesi güncellemesinin tanımlanıp tanımlanmadığı incelenir.","operating":"Seçilen yenilikler için fayda izleme raporları, kullanım verileri ve çıkarılan ders kayıtları dönem boyunca incelenir.","evidence":["Yenilik bazında fayda ve kullanım izleme raporları","Çıkarılan dersler kayıtları","Benimsenen yeniliklere ait güncellenmiş risk değerlendirmeleri"],"findings":["Devreye alınan yeni çözümlerin kullanım oranı ve sağladığı fayda ölçülmemektedir.","Çıkarılan dersler kaydedilmediği için benzer hatalar sonraki denemelerde tekrarlanmıştır."],"iso":[],"clauses":[],"itgc":""}
]},
{"objective":"APO05","purpose":"Portföy yönetimi, sınırlı kaynakların en fazla değeri üretecek BT program, hizmet ve varlıklarına yönlendirilmesini sağlar. Portföy görünürlüğü olmadığında yatırım kararları kişisel önceliklere göre verilir ve başarısız girişimler zamanında durdurulamaz. İyi işleyen portföy yönetimi, strateji ile yatırım arasındaki köprüdür.","auditFocus":"Denetçi, yatırım seçiminin tanımlı ve tutarlı kriterlerle yapılıp yapılmadığını ve onaylanan iş durumlarındaki faydaların sonradan ölçülüp ölçülmediğini inceler. Portföy envanterinin tamlığı ve düşük performanslı girişimler için durdurma ya da yeniden yönlendirme kararlarının alınıp alınmadığı da odak noktalarıdır.","keyRisks":["Yatırımların iş durumu ve önceliklendirme yapılmadan onaylanması","Beklenen faydaların ölçülmemesi nedeniyle değer üretmeyen girişimlerin sürdürülmesi","Eksik portföy envanteri nedeniyle kaynak çakışmalarının ve kayıt dışı harcamaların fark edilmemesi"],"practices":[
{"code":"APO05.01","name":"Determine the availability and sources of funds.","title":"Fon kaynaklarının ve kullanılabilir fonun belirlenmesi","expectation":"BT yatırımları için kullanılabilecek fon kaynakları (iç bütçe, proje bütçesi, finansman, abonelik modelleri) ve bunların getiri beklentisine etkisi finans birimiyle birlikte belirlenmelidir. Kullanılabilir fon miktarı portföy planlamasından önce netleşmeli ve onaylanmış olmalıdır.","design":"Fon belirleme sürecinin finans birimiyle ortak yürütülüp yürütülmediği ve farklı finansman seçeneklerinin maliyet etkilerini değerlendirip değerlendirmediği incelenir.","operating":"Son planlama döngüsündeki fon belirleme kayıtları ve finans onayları incelenir; portföye ayrılan tutar gerçekleşen tahsisle karşılaştırılır.","evidence":["BT yatırım fon planı ve finans onayı","Finansman seçenekleri analizleri","Portföy planlama dönemine ait yönetim kararı"],"findings":["Portföy planlaması kullanılabilir fon miktarı netleşmeden yapılmış, onaylanan girişimlerin bir kısmı finanse edilememiştir.","Abonelik ve sermaye harcaması seçenekleri karşılaştırılmadan finansman kararı alınmıştır."],"iso":[],"clauses":[],"itgc":""},
{"code":"APO05.02","name":"Evaluate and select programs to fund.","title":"Finanse edilecek programların değerlendirilmesi ve seçilmesi","expectation":"Program önerileri stratejik uyum, beklenen fayda, maliyet, risk ve kaynak ihtiyacını içeren iş durumlarıyla sunulmalı ve kuruma göre belirlenmiş tutarlı kriterlerle puanlanarak önceliklendirilmelidir. Seçim kararı yetkili merci tarafından alınmalı, reddedilen veya ertelenen öneriler de gerekçesiyle kaydedilmelidir.","design":"Önceliklendirme kriterlerinin yazılı, ağırlıklandırılmış ve tüm önerilere aynı şekilde uygulanacak biçimde tasarlanıp tasarlanmadığı değerlendirilir.","operating":"Dönem içindeki tüm yatırım önerileri listelenir; risk bazlı seçilen onaylanmış ve reddedilmiş önerilerde iş durumu, puanlama ve onay yetkisi yeniden incelenir.","evidence":["İş durumu belgeleri","Önceliklendirme kriterleri ve puanlama tablosu","Yatırım kurulu karar kayıtları","Onay yetki matrisi"],"findings":["Bazı projeler iş durumu hazırlanmadan doğrudan üst yönetim talimatıyla portföye alınmıştır.","Önceliklendirme kriterleri tanımlı olmasına rağmen puanlama yapılmamış, kararların dayanağı belgelenmemiştir."],"iso":[],"clauses":[],"itgc":""},
{"code":"APO05.03","name":"Monitor, optimize and report on investment portfolio performance.","title":"Yatırım portföyü performansının izlenmesi ve raporlanması","expectation":"Portföydeki programların maliyet, takvim, kapsam ve fayda performansı kuruma göre belirlenmiş aralıklarla izlenmeli ve yönetime raporlanmalıdır. Hedeflerden sapan veya iş durumu geçerliliğini yitiren girişimler için yeniden önceliklendirme, kapsam değişikliği ya da durdurma kararları alınmalıdır.","design":"Raporlamanın sapma eşikleri ve karar alma mekanizması içerip içermediği ve raporların doğrulanabilir verilere dayanıp dayanmadığı değerlendirilir.","operating":"Dönem içindeki portföy raporları incelenir; seçilen sapmalı girişimlerde raporlanan veriler proje kayıtlarıyla karşılaştırılır ve yönetim kararlarının alınıp uygulandığı doğrulanır.","evidence":["Portföy performans raporları veya gösterge panelleri","Sapma eşikleri ve eskalasyon kuralları","Durdurma veya yeniden yönlendirme kararlarına ait tutanaklar"],"findings":["Portföy raporları tüm projeleri “yeşil” göstermekte, ancak proje kayıtlarında belirgin takvim sapmaları bulunmaktadır.","İş durumu geçerliliğini yitiren bir program için durdurma değerlendirmesi yapılmamıştır."],"iso":[],"clauses":[],"itgc":""},
{"code":"APO05.04","name":"Maintain portfolios.","title":"Program, hizmet ve varlık portföylerinin güncel tutulması","expectation":"Yatırım programları ve projeler, BT ürün ve hizmetleri ile BT varlıkları için güncel ve birbiriyle ilişkilendirilmiş portföy kayıtları tutulmalıdır. Portföye ekleme, değişiklik ve çıkarma işlemleri tanımlı bir onay sürecinden geçmeli; kayıtlar kuruma göre belirlenmiş aralıklarla tamlık açısından gözden geçirilmelidir.","design":"Portföy kayıtlarının tek bir yetkili kaynakta tutulup tutulmadığı ve ekleme ile çıkarma işlemlerinin onaya bağlanıp bağlanmadığı incelenir.","operating":"Portföy kayıtları finans, satın alma ve varlık envanteri gibi bağımsız kaynaklarla karşılaştırılarak tamlık test edilir; seçilen değişikliklerin onay kayıtları incelenir.","evidence":["Proje ve program portföy listesi","BT hizmet kataloğu","BT varlık envanteri","Portföy değişiklik onay kayıtları"],"findings":["Satın alma kayıtlarında görülen bazı BT harcamaları hiçbir portföy kaydıyla ilişkilendirilmemiştir.","Hizmet kataloğunda artık sunulmayan hizmetler yer almaya devam etmektedir."],"iso":["5.9"],"clauses":[],"itgc":""},
{"code":"APO05.05","name":"Manage benefits achievement.","title":"Faydaların gerçekleşmesinin yönetilmesi","expectation":"Onaylı iş durumlarında taahhüt edilen faydalar için sahip, ölçüt, başlangıç değeri ve hedef tarih tanımlanmalı; gerçekleşme devreye alma sonrasında da izlenmelidir. Faydaların gerçekleşmediği durumlarda kök neden analiz edilmeli ve düzeltici aksiyon alınmalı ya da iş durumu güncellenmelidir.","design":"Fayda takibinin proje kapanışıyla sona ermeyip iş sahibine devredilecek şekilde tasarlanıp tasarlanmadığı değerlendirilir.","operating":"Dönem içinde faydası ölçülmesi gereken yatırımlar listelenir; seçilenlerde raporlanan fayda değerleri kaynak iş verileriyle karşılaştırılarak yeniden hesaplanır.","evidence":["Fayda kayıt defteri","Uygulama sonrası değerlendirme raporları","Fayda ölçümüne kaynak iş verileri"],"findings":["Onaylı iş durumlarında yer alan faydalar proje kapanışından sonra hiç ölçülmemiştir.","Raporlanan fayda tutarları dayanağı olmayan tahminlere dayanmakta, gerçek iş verileriyle doğrulanmamaktadır."],"iso":[],"clauses":[],"itgc":""}
]},
{"objective":"APO06","purpose":"BT bütçe ve maliyet yönetimi, BT harcamalarının şeffaf biçimde planlanmasını, izlenmesini ve hizmetlere doğru dağıtılmasını sağlar. Maliyetler görünür olmadığında değer tartışmaları öznelleşir ve bütçe aşımları geç fark edilir. Doğru maliyet bilgisi, yatırım ve kaynak önceliklendirme kararlarının da temelidir.","auditFocus":"Denetçi, BT bütçesinin portföy önceliklerine dayanıp dayanmadığını ve gerçekleşen maliyetlerin bütçeyle düzenli karşılaştırılarak sapmaların açıklanıp açıklanmadığını inceler. Maliyet dağıtım modelinin şeffaflığı ve BT kayıtlarının finans sistemiyle mutabakatı da öncelikli konulardır.","keyRisks":["Bütçe sapmalarının zamanında fark edilmemesi ve kontrolsüz harcama yapılması","Hatalı maliyet dağıtımı nedeniyle hizmet maliyetlerinin ve kârlılığın yanlış değerlendirilmesi","BT maliyetlerinin finans kayıtlarıyla mutabık olmaması nedeniyle raporlama hataları"],"practices":[
{"code":"APO06.01","name":"Manage finance and accounting.","title":"BT finans ve muhasebe yönetiminin kurulması","expectation":"BT ile ilgili tüm maliyetler, yatırımlar ve amortismanlar kurumun muhasebe sistemi ve hesap planıyla uyumlu bir yöntemle sınıflandırılmalı ve kaydedilmelidir. BT finans yönetiminin sorumlusu belirlenmiş olmalı, BT kayıtları ile finans kayıtları kuruma göre belirlenmiş aralıklarla mutabakata tabi tutulmalıdır.","design":"BT maliyet sınıflandırmasının (işletme gideri ve yatırım ayrımı, maliyet merkezleri) yazılı olup olmadığı ve mutabakat kontrolünün tanımlı olup olmadığı değerlendirilir.","operating":"Dönem içindeki mutabakatlar incelenir; seçilen BT harcamalarının doğru maliyet merkezi ve hesap sınıfına kaydedildiği dayanak belgeler üzerinden yeniden doğrulanır.","evidence":["BT maliyet sınıflandırma yönergesi veya hesap planı eşleştirmesi","BT ve finans kayıtları arasındaki mutabakat çalışmaları","Aktifleştirme ve amortisman kayıtları"],"findings":["Bazı yazılım abonelik harcamaları gerekçesiz şekilde işletme gideri yerine yatırım olarak kaydedilmiştir.","BT harcama kayıtları ile genel muhasebe arasındaki farklar açıklanmadan bırakılmıştır."],"iso":[],"clauses":[],"itgc":""},
{"code":"APO06.02","name":"Prioritize resource allocation.","title":"Kaynak tahsisinin önceliklendirilmesi","expectation":"BT kaynaklarının (bütçe, personel, altyapı) hangi kriterlere göre tahsis edileceğini belirleyen bir karar süreci ve iş birimlerinin kendi inisiyatifleriyle yapabileceği BT harcamalarına ilişkin kurallar tanımlı olmalıdır. Tahsis kararları portföy öncelikleriyle tutarlı olmalı ve gerekçesiyle kayıt altına alınmalıdır.","design":"Tahsis kurallarının iş birimi bazında harcama sınırlarını ve onaysız BT edinimlerini önleyecek kontrolleri içerip içermediği değerlendirilir.","operating":"Dönem içindeki tahsis kararları ve iş birimlerinin BT niteliğindeki harcamaları incelenerek kuralların uygulandığı ve sınır aşımlarının onaylandığı doğrulanır.","evidence":["Kaynak tahsis kuralları ve yetki limitleri","Tahsis kararlarına ait yönetim tutanakları","İş birimlerinin BT harcama raporları"],"findings":["İş birimleri BT onayı olmadan bulut hizmeti abonelikleri satın almaktadır.","Kaynak tahsis kararları gerekçesi kaydedilmeden sözlü olarak alınmaktadır."],"iso":[],"clauses":[],"itgc":""},
{"code":"APO06.03","name":"Create and maintain budgets.","title":"BT bütçesinin hazırlanması ve sürdürülmesi","expectation":"BT bütçesi portföy ve hizmet planlarındaki önceliklere dayanarak hazırlanmalı; işletme ve yatırım kalemleri, varsayımlar ve sorumlular açıkça gösterilmelidir. Bütçe yetkili merci tarafından onaylanmalı, dönem içindeki revizyonlar da tanımlı bir onay sürecinden geçmelidir.","design":"Bütçe hazırlık sürecinin portföy kararlarıyla bağlantılı olup olmadığı ve revizyonların yetki matrisine göre onaylanmasını sağlayıp sağlamadığı incelenir.","operating":"Onaylı bütçe finans sistemine yüklenen bütçeyle karşılaştırılır; dönem içindeki tüm revizyonlar listelenerek seçilenlerin onayı ve gerekçesi incelenir.","evidence":["Onaylı BT bütçesi ve bütçe varsayımları","Bütçe revizyon talepleri ve onayları","Bütçe kalemlerinin portföy listesiyle eşleştirmesi"],"findings":["Bütçe kalemleri portföydeki girişimlerle ilişkilendirilmemiş, önceki dönem harcamaları artırılarak hazırlanmıştır.","Dönem içi bütçe revizyonlarının bir kısmı yetki matrisinde belirtilen seviyede onaylanmamıştır."],"iso":[],"clauses":[],"itgc":""},
{"code":"APO06.04","name":"Model and allocate costs.","title":"Maliyet modelinin oluşturulması ve maliyetlerin dağıtılması","expectation":"BT maliyetleri, hizmet tanımlarına dayanan şeffaf bir maliyet modeliyle hizmetlere ve iş birimlerine dağıtılmalıdır. Dağıtım anahtarları belgelenmiş, iş birimleriyle mutabık kalınmış ve kuruma göre belirlenmiş aralıklarla gerçek tüketim verileriyle gözden geçirilmiş olmalıdır.","design":"Dağıtım anahtarlarının ölçülebilir tüketim verilerine dayanıp dayanmadığı ve iş birimlerinin itiraz edebileceği bir mekanizma bulunup bulunmadığı değerlendirilir.","operating":"Seçilen dönemlere ait dağıtım hesaplamaları, kaynak tüketim verileri ve onaylı dağıtım anahtarları kullanılarak yeniden hesaplanır.","evidence":["BT maliyet modeli ve dağıtım anahtarları dokümantasyonu","Dağıtım hesaplama dosyaları","İş birimlerine gönderilen maliyet yansıtma raporları"],"findings":["Maliyetler gerçek tüketim yerine sabit oranlarla dağıtılmakta ve bu oranlar uzun süredir güncellenmemektedir.","Dağıtım hesaplamaları elle hazırlanan tablolarda yapılmakta ve yeniden hesaplamada farklar tespit edilmiştir."],"iso":[],"clauses":[],"itgc":""},
{"code":"APO06.05","name":"Manage costs.","title":"Maliyetlerin bütçeye göre izlenmesi ve yönetilmesi","expectation":"Gerçekleşen BT maliyetleri kuruma göre belirlenmiş aralıklarla bütçeyle karşılaştırılmalı; önemli sapmalar tanımlı eşiklere göre belirlenip analiz edilmeli ve sorumlusuna iletilmelidir. Sapmalar için açıklama, düzeltici aksiyon ve gerekiyorsa tahmin güncellemesi yapılmalı, maliyet tasarruf fırsatları da izlenmelidir.","design":"Maliyet izleme sürecinin sapma eşiklerini, açıklama zorunluluğunu ve eskalasyon kurallarını içerip içermediği değerlendirilir.","operating":"Dönem içindeki tüm bütçe-gerçekleşen raporları incelenir; eşiği aşan sapmalar için açıklama ve aksiyonların zamanında yapıldığı doğrulanır, seçilen tutarlar finans sistemiyle karşılaştırılır.","evidence":["Bütçe-gerçekleşen karşılaştırma raporları","Sapma analizleri ve açıklamaları","Maliyet tahmini güncellemeleri","Maliyet raporlarının görüşüldüğü yönetim toplantı tutanakları"],"findings":["Eşiği aşan bütçe sapmaları için açıklama talep edilmemiş ve aksiyon alınmamıştır.","Yönetime raporlanan gerçekleşen maliyetler finans sistemindeki tutarlarla uyuşmamaktadır."],"iso":[],"clauses":[],"itgc":""}
]},
{"objective":"APO07","purpose":"BT hizmetlerinin kalitesi ve güvenliği büyük ölçüde doğru yetkinlikteki kişilerin doğru rollerde bulunmasına bağlıdır. Personel eksikliği, kilit kişilere aşırı bağımlılık ve yetersiz eğitim; hata, kesinti ve güvenlik olaylarına zemin hazırlar. Dış kaynak ve sözleşmeli personelin de aynı kurallara tabi olması, insan kaynaklı riskin bütünüyle yönetilmesi için gereklidir.","auditFocus":"Denetçi, kilit personel bağımlılığının tespit edilip azaltıldığını, yetkinlik ve eğitim ihtiyaçlarının rol bazında izlendiğini ve işe giriş ile ayrılış süreçlerinin güvenlik gereksinimlerini kapsadığını inceler. Sözleşmeli personelin politika kabulü, gizlilik taahhüdü ve sözleşme sonunda erişimlerinin kapatılması özellikle örneklenir; kişisel veriler içeren kanıtlar gizlilik gözetilerek ele alınır.","keyRisks":["Kritik bilgi ve yetkinliğin tek kişiye bağımlı kalması nedeniyle hizmet sürekliliğinin tehlikeye girmesi","Yetersiz eğitimli personelin hata veya güvenlik ihlaline yol açması","Sözleşmeli personelin politika dışında çalışması veya sözleşme bitiminde erişimlerinin açık kalması"],"practices":[
{"code":"APO07.01","name":"Acquire and maintain adequate and appropriate staffing.","title":"Yeterli ve uygun BT personel kadrosunun sağlanması","expectation":"BT personel ihtiyacı (iç ve dış kaynak) kuruma göre belirlenmiş aralıklarla ve önemli organizasyonel veya teknolojik değişikliklerde değerlendirilmelidir. İşe alım rol gereksinimlerine dayanmalı; işe alım öncesi tarama ilgili mevzuat ve rolün hassasiyetiyle orantılı yapılmalı, iş sözleşmeleri güvenlik ve gizlilik yükümlülüklerini içermelidir.","design":"Kadro planlamasının iş hacmi ve risk değerlendirmesine dayanıp dayanmadığı ve işe alım sürecinin tarama ile güvenlik taahhüdü adımlarını zorunlu kılıp kılmadığı değerlendirilir.","operating":"Dönem içinde işe alınan BT personelinin tam listesi İK sisteminden alınır; risk bazlı seçilen kişilerde tarama kaydı, imzalı sözleşme ve gizlilik taahhüdü kişisel veriler maskelenerek incelenir.","evidence":["BT kadro planı ve ihtiyaç analizi","İşe alım kayıtları ve rol gereksinim tanımları","Tarama tamamlama kayıtları (kişisel ayrıntılar maskelenmiş)","İmzalı iş sözleşmesi ve gizlilik taahhüdü örnekleri"],"findings":["Yüksek yetkili bazı BT rollerine işe alınan kişiler için tarama adımının tamamlandığına dair kayıt bulunmamaktadır.","Kadro ihtiyacı son altyapı dönüşümünden sonra yeniden değerlendirilmemiş, kritik ekiplerde sürekli fazla mesai oluşmuştur."],"iso":["6.1","6.2"],"clauses":["7.1"],"itgc":""},
{"code":"APO07.02","name":"Identify key IT personnel.","title":"Kilit BT personelinin belirlenmesi ve kişi bağımlılığının azaltılması","expectation":"Kritik sistem ve süreçlerde tek kişiye bağımlılık yaratan roller tespit edilmeli; bu roller için yedek personel, halef planı ve belgelenmiş çalışma talimatları bulunmalıdır. Görev rotasyonu veya kesintisiz izin gibi önlemler kuruma göre belirlenmiş şekilde uygulanmalıdır.","design":"Kilit personel analizinin kritik sistemlerle ilişkilendirilip ilişkilendirilmediği ve her kilit rol için yedekleme ve bilgi aktarım önlemi tanımlanıp tanımlanmadığı değerlendirilir.","operating":"Seçilen kilit rollerde yedek kişinin yetkin olduğu (ör. dönem içinde görevi fiilen üstlendiği) ve çalışma talimatlarının güncel olduğu inceleme ve görüşmeyle doğrulanır.","evidence":["Kilit personel ve tek kişiye bağımlılık analizi","Halef ve yedekleme planları","Kritik süreçlere ait güncel çalışma talimatları","Bilgi aktarımı veya gölge çalışma kayıtları"],"findings":["Kritik bir uygulamanın bakımını yalnızca tek bir uzman bilmekte, yedek personel veya güncel dokümantasyon bulunmamaktadır.","Kilit personel listesi hazırlanmış ancak yedeklerin görevi üstlenebilecek yetkinlikte olup olmadığı hiç denenmemiştir."],"iso":["5.37"],"clauses":[],"itgc":""},
{"code":"APO07.03","name":"Maintain the skills and competencies of personnel.","title":"Personel beceri ve yetkinliklerinin sürdürülmesi","expectation":"Personelin rolüne göre gereken yetkinliklere sahip olup olmadığı kuruma göre belirlenmiş aralıklarla değerlendirilmeli; açıklar için eğitim, sertifikasyon veya mentorluk planlanmalıdır. Bilgi güvenliği farkındalık eğitimi tüm BT personeli için, role özgü güvenlik eğitimleri ise ayrıcalıklı erişime sahip personel için planlanmalı ve tamamlanma izlenmelidir.","design":"Eğitim planının yetkinlik açıklarına dayanıp dayanmadığı ve zorunlu eğitimlerin tamamlanmadığı durumlar için eskalasyon tanımlanıp tanımlanmadığı değerlendirilir.","operating":"Eğitim yönetim sisteminden dönem boyunca yapılan zorunlu eğitim atamalarının tam listesi alınır; tamamlanma oranları ve seçilen ayrıcalıklı kullanıcıların eğitim kayıtları incelenir.","evidence":["Yetkinlik değerlendirme sonuçları","Dönemsel eğitim planı","Eğitim yönetim sisteminden tamamlanma raporları","Sertifika ve katılım kayıtları"],"findings":["Zorunlu güvenlik farkındalık eğitimini tamamlamayan personel için takip ve eskalasyon yapılmamaktadır.","Eğitim planı yetkinlik değerlendirmesine dayanmamakta, bireysel taleplere göre oluşturulmaktadır."],"iso":["6.3"],"clauses":["7.2","7.3"],"itgc":""},
{"code":"APO07.04","name":"Assess and recognize/reward employee job performance.","title":"Personel performansının değerlendirilmesi ve ödüllendirilmesi","expectation":"BT personelinin performansı, kurum hedeflerinden türetilmiş bireysel hedeflere ve rol sorumluluklarına (güvenlik ve uyum sorumlulukları dahil) göre zamanında değerlendirilmelidir. Sonuçlar gelişim planlarına, tanınma ve ödüllendirmeye bağlanmalı; düşük performans için tanımlı bir iyileştirme süreci bulunmalıdır.","design":"Bireysel hedeflerin BT hedefleriyle bağlantılı olup olmadığı ve kontrol sorumluluklarının değerlendirme kriterleri arasında yer alıp almadığı incelenir.","operating":"Değerlendirme döngüsündeki tüm BT personelinin tamamlanma durumu kontrol edilir; seçilen değerlendirmelerde hedef belgeleri ve gelişim planları kişisel veriler gizlilikle ele alınarak incelenir.","evidence":["Performans yönetimi politikası","Değerlendirme tamamlanma raporu","Anonimleştirilmiş hedef kartı ve gelişim planı örnekleri"],"findings":["BT personelinin bir kısmı için değerlendirme dönemi kapandığı halde performans değerlendirmesi yapılmamıştır.","Bireysel hedefler BT stratejisi ve kontrol sorumluluklarıyla ilişkilendirilmemiştir."],"iso":[],"clauses":[],"itgc":""},
{"code":"APO07.05","name":"Plan and track the usage of IT and business human resources.","title":"BT ve iş tarafı insan kaynağı kullanımının planlanması ve izlenmesi","expectation":"BT ile ilgili görevler üstlenen iş ve BT personeline yönelik mevcut ve gelecekteki talep kapasite planlamasıyla izlenmelidir. Kaynak açıkları ve fazlalıkları belirlenmeli; işe alım, yeniden görevlendirme veya dış kaynak kararlarına girdi oluşturmalı ve portföy kararlarıyla tutarlı olmalıdır.","design":"Kaynak planlamasının portföydeki projeler ve operasyonel iş yüküyle ilişkilendirilip ilişkilendirilmediği ve kaynak açıklarının yönetime raporlanıp raporlanmadığı değerlendirilir.","operating":"Dönem içindeki kaynak planı gerçekleşen kullanımla (ör. zaman kayıtları) karşılaştırılır; seçilen kaynak açıkları için alınan kararlar incelenir.","evidence":["Kaynak kapasite planı","Zaman takip veya kaynak kullanım raporları","Kaynak açığı raporları ve ilgili yönetim kararları"],"findings":["Projelere atanan bazı kişilerin toplam iş yükü kapasitelerini aşmakta, ancak bu durum planlama sırasında görünür değildir.","İş birimlerinde BT görevi üstlenen personel kaynak planlamasına dahil edilmemiştir."],"iso":[],"clauses":["7.1"],"itgc":""},
{"code":"APO07.06","name":"Manage contract staff.","title":"Sözleşmeli ve danışman personelin yönetimi","expectation":"Danışman ve sözleşmeli personel işe başlamadan önce kurum politikalarını ve gizlilik yükümlülüklerini kabul etmeli; sözleşmelerde güvenlik gereksinimleri, fikri mülkiyet ve performans beklentileri yer almalıdır. Bu kişilerin erişimleri sözleşme süresiyle sınırlandırılmalı, sözleşme bitiminde veya görev değişikliğinde zamanında kapatılmalı ve kurum varlıkları iade alınmalıdır.","design":"Sözleşmeli personel envanterinin tutulup tutulmadığı, erişim hesaplarının bitiş tarihine bağlanıp bağlanmadığı ve sözleşme sonu sürecinin erişim kapatmayı tetikleyip tetiklemediği değerlendirilir.","operating":"Dönem içinde sözleşmesi sona eren tüm dış personelin listesi alınır; risk bazlı seçilenlerde erişim kapatma tarihleri salt okunur sistem kayıtlarıyla karşılaştırılır, aktif sözleşmelilerde gizlilik taahhüdü kontrol edilir.","evidence":["Sözleşmeli ve danışman personel envanteri ile sözleşme süreleri","İmzalı gizlilik ve politika kabul formları","Hesap bitiş tarihleri ve erişim kapatma kayıtları","Varlık iade tutanakları"],"findings":["Sözleşmesi sona eren bazı danışmanların kullanıcı hesapları sözleşme bitiminden sonra da aktif kalmıştır.","Dış kaynak personelinin bir kısmı için imzalı gizlilik taahhüdü bulunmamaktadır."],"iso":["5.20","6.2","6.5","6.6"],"clauses":[],"itgc":"access"}
]}
]
);
